/* Direct decompilation of FUN_8009A388. */
uint16 player_animation_start(uint16 dir_buttons)
{
    PLAYER *player = g_player;
    uint16 dir = player->dir;
    const PLAYER_DIRECTION *desc;
    if (dir_buttons == 0x1000)
        dir = 0;
    if (dir_buttons == 0x3000)
        dir = 1;
    if (dir_buttons == 0x2000)
        dir = 2;
    if (dir_buttons == 0x6000)
        dir = 3;
    if (dir_buttons == 0x4000)
        dir = 4;
    if (dir_buttons == 0xc000)
        dir = 5;
    if (dir_buttons == 0x8000)
        dir = 6;
    if (dir_buttons == 0x9000)
        dir = 7;
    desc = dir_desc((sint16)dir);
    player->dir_x = desc->x_sign;
    player->dir_z = desc->z_sign;
    if (desc->x_sign != 0)
        player->facing_x = desc->x_sign;
    if (desc->z_sign != 0)
        player->facing_z = desc->z_sign;
    return dir;
}

