static sint16 player_clamp_to_scr(uint32 buttons)
{
    PLAYER *player = g_player;
    sint16 mode;
    if (g_session.stage == 0x0b && g_hq_weapon_area_enabled == 0)
        return 0;
    mode = (buttons & 0x80) != 0;
    if ((g_input.pressed & PADRright) != 0)
    {
        INVENTORY_SLOT *sel = &player->inventory[g_sel_weapon_slot];
        if (sel->type == 0x2a || sel->type == 0x8c)
            mode = 2;
    }
    if (player->special_weapon_ticks != 0)
    {
        if (mode == 0 || (g_render_state.frame & 0x1f) != 0)
            mode = 0;
        else
            sound_play_positional(0x1e, 0, 0x89, player->col.x, player->col.y, player->col.z);
    }
    return mode;
}

static void draw_player_pose(PLAYER *player, sint32 process_mirror_toggle)
{
    ANIM *anim = &player->animation;
    uint32 frame_id;
    sint32 mirror = player->facing_x;
    frame_id = animation_update(anim);
    if (player->damage_cooldown != 0 && (g_render_state.frame & 3) == 0)
        player->col.flash_clut_ticks = 1;
    if (process_mirror_toggle && (anim->flags & 2) != 0)
    {
        anim->mirrored ^= 1;
        anim->flags &= ~2;
    }
    if (process_mirror_toggle && anim->mirrored != 0)
        mirror = -mirror;
    if (process_mirror_toggle)
    {
        /* 8009CDF8..8009CE08: seed the next FrameObject's signed lighting /
         * depth adjustment before FUN_8008D108 consumes that record. */
        g_next_frame_object->light_delta = player->light_delta;
        player->light_delta = 0;
    }
    /* 0x8009CE08..0x8009CE58: the player uses the same world-sprite builder
     * as every other actor.  +0x44 is its persistent POLY_FT4 and +0xA8 its
     * 0x30-byte VRAM descriptor. */
    render_world_spr(frame_id, player->col.x, player->col.y, player->col.z, mirror, g_default_spr_scale, g_default_spr_scale, &player->col.prim, 0, 2, &player->vram_desc, 0);
}

static void draw_player_frame(PLAYER *player, uint32 frame_id)
{
    render_world_spr(frame_id, player->col.x, player->col.y, player->col.z, player->facing_x, g_default_spr_scale, g_default_spr_scale, &player->col.prim, 0, 2, &player->vram_desc, 0);
}

