/* Original: FUN_800A119C. */
void weapon_selection_update(void)
{
    uint32 pressed = g_input.held & ~g_input.prev;
    sint32 attempts;

    if ((pressed & (PADL1 | PADL2)) == 0)
        return;
    for (attempts = 0; attempts < 16; ++attempts)
    {
        if (pressed & PADL1)
            g_sel_weapon_slot = (g_sel_weapon_slot - 1) & 15;
        else
            g_sel_weapon_slot = (g_sel_weapon_slot + 1) & 15;
        if (g_player->inventory[g_sel_weapon_slot].type != 0)
            break;
    }
}

/* Original: FUN_800A1AD4. */
__declspec(noinline) sint32 player_inside_xz_box(sint32 x, sint32 z, sint32 width, sint32 depth)
{
    sint32 half_x = width / 2, half_z = depth / 2;
    const uint32 half_x_word = half_x;
    sint32 left = x - half_x_word;
    sint32 right = x + half_x_word;
    const uint32 half_z_word = half_z;
    sint32 back = z - half_z_word;
    sint32 front = z + half_z_word;
    return g_player_world.x >= left && g_player_world.x <= right && g_player_world.z <= front && g_player_world.z >= back;
}

/* Push the player out of a moving box */
/* Original: FUN_800ACDA0. */
__declspec(noinline) void player_push_out_of_box(sint32 x, sint32 y, sint32 z, sint32 half_x, sint32 height, sint32 half_z)
{
    PLAYER *player = g_player;
    const uint32 half_x_word = half_x;
    sint32 left = (x - half_x_word), right = (x + half_x_word);
    sint32 half_y = height / 2;
    const uint32 half_y_word = half_y;
    sint32 top = (y - half_y_word), bottom = (y + half_y_word);
    const uint32 half_z_word = half_z;
    sint32 back = (z - half_z_word), front = (z + half_z_word);
    sint32 old_x = (uint32)player->col.x - g_player_world.delta_x;
    sint32 old_y = (uint32)player->col.y - g_player_world.delta_y;
    sint32 old_z = (uint32)player->col.z - g_player_world.delta_z;
    if (g_player_world.y < top || bottom < g_player_world.y || g_player_world.x <= left || right <= g_player_world.x || g_player_world.z <= back || front <= g_player_world.z)
        return;
    if (g_session.scuba_active)
    {
        if (old_y < top)
        {
            player->col.y = top - 0x100u;
            return;
        }
        if (bottom < old_y)
        {
            player->col.y = bottom + 0x100u;
            return;
        }
    }
    if (g_player_world.delta_x == 0 && g_player_world.delta_z == 0)
    {
        player->col.x = x;
        player->col.z = back;
    }
    if (!(left < old_x) && g_player_world.delta_x > 0)
        player->col.x = left;
    if (!(old_x < right) && g_player_world.delta_x < 0)
        player->col.x = right;
    if (!(back < old_z) && g_player_world.delta_z > 0)
        player->col.z = back;
    if (!(old_z < front) && g_player_world.delta_z < 0)
        player->col.z = front;
}

